#!/usr/bin/env bash\n\n# SMS Service Supabase Setup Script\n# This script sets up the necessary environment variables and deploys the SMS Edge Function\n\necho \"🚀 Setting up SMS Service with Supabase...\"\n\n# Check if Supabase CLI is installed\nif ! command -v supabase &> /dev/null; then\n    echo \"❌ Supabase CLI is not installed. Please install it first:\"\n    echo \"npm install -g supabase\"\n    exit 1\nfi\n\n# Check if .env file exists\nif [ ! -f \".env\" ]; then\n    echo \"❌ .env file not found. Please create one with your environment variables.\"\n    exit 1\nfi\n\n# Load environment variables\nsource .env\n\n# Check required environment variables\nif [ -z \"$VITE_AFRICASTALKING_API_KEY\" ] || [ -z \"$VITE_AFRICASTALKING_USERNAME\" ] || [ -z \"$VITE_AFRICASTALKING_FROM\" ]; then\n    echo \"❌ Missing required Africa's Talking environment variables:\"\n    echo \"   - VITE_AFRICASTALKING_API_KEY\"\n    echo \"   - VITE_AFRICASTALKING_USERNAME\"\n    echo \"   - VITE_AFRICASTALKING_FROM\"\n    exit 1\nfi\n\necho \"✅ Environment variables found\"\n\n# Set Supabase secrets for the Edge Function\necho \"🔐 Setting Supabase secrets...\"\n\nsupabase secrets set AFRICASTALKING_API_KEY=\"$VITE_AFRICASTALKING_API_KEY\"\nsupabase secrets set AFRICASTALKING_USERNAME=\"$VITE_AFRICASTALKING_USERNAME\"\nsupabase secrets set AFRICASTALKING_FROM=\"$VITE_AFRICASTALKING_FROM\"\n\necho \"✅ Supabase secrets set successfully\"\n\n# Deploy the Edge Function\necho \"📦 Deploying SMS Edge Function...\"\nsupabase functions deploy send-sms\n\nif [ $? -eq 0 ]; then\n    echo \"✅ SMS Edge Function deployed successfully\"\nelse\n    echo \"❌ Failed to deploy SMS Edge Function\"\n    exit 1\nfi\n\n# Run database migrations\necho \"🗄️  Running database migrations...\"\nsupabase db push\n\nif [ $? -eq 0 ]; then\n    echo \"✅ Database migrations completed successfully\"\nelse\n    echo \"❌ Failed to run database migrations\"\n    exit 1\nfi\n\necho \"\"\necho \"🎉 SMS Service setup completed successfully!\"\necho \"\"\necho \"📋 Summary:\"\necho \"   ✅ Environment variables configured\"\necho \"   ✅ Supabase secrets set\"\necho \"   ✅ SMS Edge Function deployed\"\necho \"   ✅ Database migrations applied\"\necho \"\"\necho \"🔧 Next steps:\"\necho \"   1. Test SMS functionality in your application\"\necho \"   2. Monitor SMS logs in the database\"\necho \"   3. Check Supabase Edge Function logs for any issues\"\necho \"\"\necho \"📞 SMS Features Available:\"\necho \"   • Welcome SMS for new patient registrations\"\necho \"   • Appointment confirmation SMS\"\necho \"   • Appointment reminder SMS\"\necho \"   • Custom SMS messages\"\necho \"   • SMS history tracking\"\necho \"\"\n